/** 統一的成功／失敗回應 */
export const ok = (data) => ({ ok: true, data });
/** @param {ErrCode} code */
export const fail = (code, message, hint) => ({ ok: false, error: { code, message, ...(hint ? { hint } : {}) } });

export class ListioError extends Error {
  /** @param {ErrCode} code */
  constructor(code, message, hint) {
    super(message);
    this.name = 'ListioError';
    this.code = code;
    this.hint = hint;
  }
}

